from abc import ABC, abstractmethod


class Penyimpan(ABC):
    """Kontrak: apa pun yang menyimpan catatan wajib bisa simpan & ambil."""

    @abstractmethod
    def simpan(self, kunci, nilai):
        pass

    @abstractmethod
    def ambil(self, kunci):
        pass

    def simpan_banyak(self, pasangan):    # method BIASA, isinya sudah lengkap
        for kunci, nilai in pasangan:
            self.simpan(kunci, nilai)     # memakai method yang belum ditulis


class PenyimpanMemori(Penyimpan):         # implementasi konkret pertama
    def __init__(self):
        self.data = {}

    def simpan(self, kunci, nilai):
        self.data[kunci] = nilai

    def ambil(self, kunci):
        return self.data.get(kunci)


class PenyimpanBaris(Penyimpan):          # implementasi konkret kedua
    def __init__(self):
        self.baris = []

    def simpan(self, kunci, nilai):
        self.baris.append(f"{kunci}={nilai}")

    def ambil(self, kunci):
        for b in self.baris:
            k, _, v = b.partition("=")
            if k == kunci:
                return v
        return None


class PenyimpanSetengahJadi(Penyimpan):
    def simpan(self, kunci, nilai):       # method 'ambil' LUPA ditulis
        print("disimpan:", kunci)


# Kode di bawah ini tidak peduli gudangnya jenis apa: kontraknya menjamin
# simpan(), ambil(), dan simpan_banyak() PASTI ada di dua-duanya.
for gudang in (PenyimpanMemori(), PenyimpanBaris()):
    gudang.simpan_banyak([("nama", "Levi"), ("kota", "Bontang")])
    print(type(gudang).__name__, "->", gudang.ambil("kota"))

try:
    Penyimpan()                 # class kontrak memang TIDAK boleh jadi objek
except TypeError as e:
    print("TypeError:", e)

try:
    PenyimpanSetengahJadi()      # turunan yang belum lengkap ikut ditolak
except TypeError as e:
