def log_panggilan(fungsi):
    def wrapper(*args, **kwargs):
        print(f"Memanggil {fungsi.__name__} dengan args={args}, kwargs={kwargs}")
        hasil = fungsi(*args, **kwargs)
        print(f"{fungsi.__name__} mengembalikan: {hasil}")
        return hasil
    return wrapper


@log_panggilan
def tambah(a, b):
    return a + b


